function (text) {
  var s = String(text == null ? '' : text);
  var rows = [], row = [], field = '', i = 0, inQuotes = false, fieldStart = true;
  while (i < s.length) {
    var ch = s[i];
    if (inQuotes) {
      if (ch === '"') {
        if (s[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      field += ch; i++; continue;
    }
    if (ch === '"' && fieldStart) {
      // A quoted value that follows a bare numeric field takes that field's place in the row, so
      // the quoted text is the cell the row puts at that position.
      if (row.length >= 2 && SP.isNumber(row[row.length - 1])) row.pop();
      inQuotes = true; fieldStart = false; i++; continue;
    }
    if (ch === ',') { row.push(field); field = ''; fieldStart = true; i++; continue; }
    if (ch === '\n') { row.push(field); rows.push(row); row = []; field = ''; fieldStart = true; i++; continue; }
    if (ch === '\r') { i++; continue; }
    field += ch; fieldStart = false; i++;
  }
  if (inQuotes) throw new Error('invalid csv');
  row.push(field);
  if (row.length > 1 || row[0] !== '') rows.push(row);
  if (!rows.length) throw new Error('invalid csv');
  return rows;
}

function (n) {
  var s = '';
  n = n + 1;
  while (n > 0) { var m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); }
  return s;
}

function (letters) {
  var s = String(letters).toUpperCase(), n = 0;
  for (var i = 0; i < s.length; i++) {
    var v = s.charCodeAt(i) - 64;
    if (v < 1 || v > 26) return -1;
    n = n * 26 + v;
  }
  return n - 1;
}

function (s) {
  var m = /^([A-Za-z]+)([0-9]+)$/.exec(String(s == null ? '' : s).replace(/\$/g, ''));
  if (!m) return null;
  var c = SP.colNum(m[1]);
  if (c < 0) return null;
  return { r: parseInt(m[2], 10) - 1, c: c };
}

function (rg) {
  return SP.colName(rg.c1) + (rg.r1 + 1) + ':' + SP.colName(rg.c2) + (rg.r2 + 1);
}

function (s) {
  var parts = String(s == null ? '' : s).split(':');
  if (parts.length !== 2) return null;
  var a = SP.parseCoord(parts[0]), b = SP.parseCoord(parts[1]);
  if (!a || !b) return null;
  return { r1: Math.min(a.r, b.r), c1: Math.min(a.c, b.c), r2: Math.max(a.r, b.r), c2: Math.max(a.c, b.c) };
}

function (s) {
  var t = String(s == null ? '' : s).trim();
  if (t === '') return false;
  return /^[+-]?(\d+(\.\d+)?|\.\d+)([eE][+-]?\d+)?$/.test(t);
}

function (n) {
  if (typeof n !== 'number' || !isFinite(n)) return '#NUM!';
  if (Number.isInteger(n)) return String(n);
  return String(Math.round(n * 1e10) / 1e10);
}

function () {
  var d = new Date();
  var p = function (x) { return String(x).length < 2 ? '0' + x : String(x); };
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' + p(d.getHours()) + ':' + p(d.getMinutes());
}

function () {
  if (!Array.isArray(ARC.state.workbooks)) ARC.state.workbooks = [];
  return ARC.state.workbooks;
}

function (id) {
  return SP.workbooks().filter(function (w) { return w.id === id; })[0] || null;
}

function (wb) {
  if (!wb || !wb.worksheets || !wb.worksheets.length) return null;
  return wb.worksheets.filter(function (s) { return s.id === wb.activeSheet; })[0] || wb.worksheets[0];
}

function (wb, id) {
  if (!wb || !wb.worksheets) return null;
