}

function (sheet) {
  var s = (sheet && sheet.sel) || { r: 0, c: 0, r2: 0, c2: 0 };
  var r = s.r || 0, c = s.c || 0, r2 = (s.r2 == null ? r : s.r2), c2 = (s.c2 == null ? c : s.c2);
  return { r1: Math.min(r, r2), c1: Math.min(c, c2), r2: Math.max(r, r2), c2: Math.max(c, c2) };
}

function (sheet) {
  var minR = Infinity, minC = Infinity, maxR = -1, maxC = -1;
  var cells = (sheet && sheet.cells) || {};
  for (var coord in cells) {
    if (!Object.prototype.hasOwnProperty.call(cells, coord)) continue;
    if (cells[coord] === '' || cells[coord] == null) continue;
    var p = SP.parseCoord(coord);
    if (!p) continue;
    if (p.r < minR) minR = p.r;
    if (p.c < minC) minC = p.c;
    if (p.r > maxR) maxR = p.r;
    if (p.c > maxC) maxC = p.c;
  }
  if (maxR < 0) return null;
  return { r1: minR, c1: minC, r2: maxR, c2: maxC };
}

function (sheet) {
  var sel = SP.normSel(sheet);
  if (sel.r1 !== sel.r2 || sel.c1 !== sel.c2) return sel;
  return SP.usedRange(sheet) || sel;
}

function (sheet) {
  var maxR = 0, maxC = 0;
  var cells = (sheet && sheet.cells) || {};
  for (var coord in cells) {
    if (!Object.prototype.hasOwnProperty.call(cells, coord)) continue;
    var p = SP.parseCoord(coord);
    if (!p) continue;
    if (p.r > maxR) maxR = p.r;
    if (p.c > maxC) maxC = p.c;
  }
  var sel = SP.normSel(sheet);
  if (sel.r2 > maxR) maxR = sel.r2;
  if (sel.c2 > maxC) maxC = sel.c2;
  return {
    rows: Math.min(Math.max(20, maxR + 3), 60),
    cols: Math.min(Math.max(10, maxC + 3), 26)
  };
}

function (sheet, axis, at, count, mode) {
  if (!sheet) return;
  var list = SP.workbooks();
  list.forEach(function (wb) {
    var owns = (wb.worksheets || []).filter(function (s) { return s.id === sheet.id; }).length > 0;
    if (!owns) return;
    (wb.worksheets || []).forEach(function (s) {
      if (!s.pivot || s.pivot.sourceSheetId !== sheet.id) return;
      var rg = SP.parseRange(s.pivot.range);
      if (!rg) return;
      var a1 = axis === 'row' ? rg.r1 : rg.c1;
      var a2 = axis === 'row' ? rg.r2 : rg.c2;
      if (mode === 'insert') {
        if (a1 >= at) a1 += count;
        if (a2 >= at) a2 += count;
      } else {
        if (a1 >= at + count) a1 -= count; else if (a1 >= at) a1 = at;
        if (a2 >= at + count) a2 -= count; else if (a2 >= at) a2 = at - 1;
        if (a2 < a1) a2 = a1;
      }
      s.pivot.range = SP.rangeName(axis === 'row'
        ? { r1: a1, r2: a2, c1: rg.c1, c2: rg.c2 }
        : { r1: rg.r1, r2: rg.r2, c1: a1, c2: a2 });
    });
  });
}

function () {
  var r = ARC.route();
  if (r.name !== 'workbook') return null;
  return SP.wb(r.params[0]);
}

function (sheet, coord, guard) {
  var cells = (sheet && sheet.cells) || {};
  var raw = cells[coord];
  if (raw === undefined || raw === null || raw === '') return { type: 'empty', num: 0, text: '', disp: '' };
  var s = String(raw);
  if (s.charAt(0) === '=') {
    if (guard.indexOf(coord) >= 0) return { type: 'err', disp: '#REF!' };
    guard.push(coord);
    var res;
    try {
      res = SP.evalFormula(s.slice(1), sheet, guard);
    } catch (e) {
      res = { type: 'err', disp: (e && e.message) ? e.message : '#ERROR!' };
    }
    guard.pop();
    return res;
  }
  if (SP.isNumber(s)) return { type: 'num', num: Number(s), text: s, disp: s };
  return { type: 'text', num: NaN, text: s, disp: s };
}

function (sheet) {
  var out = {}, cells = (sheet && sheet.cells) || {};
  for (var coord in cells) {
    if (!Object.prototype.hasOwnProperty.call(cells, coord)) continue;
    out[coord] = SP.cellValue(sheet, coord, []).disp;
  }
  return out;
}

function (expr) {
  var out = [], i = 0;
  while (i < expr.length) {
    var ch = expr[i];
    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') { i++; continue; }
    if ((ch >= '0' && ch <= '9') || ch === '.') {
      var j = i;
      while (j < expr.length && ((expr[j] >= '0' && expr[j] <= '9') || expr[j] === '.')) j++;
      out.push({ t: 'num', v: parseFloat(expr.slice(i, j)) });
      i = j;
      continue;
    }
    if (/[A-Za-z_$]/.test(ch)) {
      var k = i;
      while (k < expr.length && /[A-Za-z0-9_$]/.test(expr[k])) k++;
      out.push({ t: 'name', v: expr.slice(i, k) });
      i = k;
      continue;
    }
    if ('+-*/():,'.indexOf(ch) >= 0) { out.push({ t: 'op', v: ch }); i++; continue; }
    if (ch === '#') {
      var h = i;
      while (h < expr.length && '+-*/(),'.indexOf(expr[h]) < 0) h++;
      out.push({ t: 'err', v: expr.slice(i, h).toUpperCase() });
      i = h;
      continue;
    }
    throw new CalcError('#ERROR!');
  }
  return out;
}

function (expr, sheet, guard) {
  var tokens = SP.tokenize(String(expr));
  var pos = 0;

  function peek() { return tokens[pos]; }
  function next() { return tokens[pos++]; }

  function numOf(v) {
    if (!v) throw new CalcError('#ERROR!');
    if (v.kind === 'num') return v.num;
    if (v.kind === 'empty') return 0;
    throw new CalcError('#ERROR!');
  }

  function cellToValue(ref) {
    if (ref.r < 0 || ref.c < 0 || ref.r > 5000 || ref.c > 200) throw new CalcError('#REF!');
    var cv = SP.cellValue(sheet, SP.coord(ref.r, ref.c), guard);
    if (cv.type === 'err') throw new CalcError(cv.disp);
    if (cv.type === 'empty') return { kind: 'num', num: 0 };
    if (cv.type === 'num') return { kind: 'num', num: cv.num };
    return { kind: 'text', text: cv.text };
  }

  function collectNumbers(args) {
    var nums = [], count = 0;
    for (var a = 0; a < args.length; a++) {
      var arg = args[a];
      if (arg.kind === 'range') {
        for (var r = arg.r1; r <= arg.r2; r++) {
          for (var c = arg.c1; c <= arg.c2; c++) {
            var cv = SP.cellValue(sheet, SP.coord(r, c), guard);
            if (cv.type === 'err') throw new CalcError(cv.disp);
            if (cv.type === 'num') { nums.push(cv.num); count++; }
          }
        }
      } else if (arg.kind === 'num') { nums.push(arg.num); count++; }
    }
    return { nums: nums, count: count };
  }

  function applyFunction(name, args) {
    if (['SUM', 'AVERAGE', 'COUNT', 'MIN', 'MAX'].indexOf(name) < 0) throw new CalcError('#NAME?');
    var got = collectNumbers(args);
    var nums = got.nums;
    if (name === 'COUNT') return { kind: 'num', num: got.count };
    if (!nums.length) {
      if (name === 'SUM') return { kind: 'num', num: 0 };
      if (name === 'MIN' || name === 'MAX') return { kind: 'num', num: 0 };
      throw new CalcError('#DIV/0!');
    }
    var total = 0;
    for (var i = 0; i < nums.length; i++) total += nums[i];
    if (name === 'SUM') return { kind: 'num', num: total };
    if (name === 'AVERAGE') return { kind: 'num', num: total / nums.length };
    if (name === 'MIN') return { kind: 'num', num: Math.min.apply(null, nums) };
    return { kind: 'num', num: Math.max.apply(null, nums) };
  }

  function parseFactor() {
    var t = next();
    if (!t) throw new CalcError('#ERROR!');
    if (t.t === 'num') return { kind: 'num', num: t.v };
    if (t.t === 'err') throw new CalcError(t.v || '#REF!');
    if (t.t === 'op' && t.v === '(') {
      var v = parseExpr();
      var close = next();
      if (!close || close.t !== 'op' || close.v !== ')') throw new CalcError('#ERROR!');
      return v;
    }
    if (t.t === 'op' && t.v === '-') return { kind: 'num', num: -numOf(parseFactor()) };
    if (t.t === 'op' && t.v === '+') return parseFactor();
    if (t.t === 'name') {
      var after = peek();
      if (after && after.t === 'op' && after.v === '(') {
        pos++;
        return callFunction(t.v.toUpperCase());
      }
      var ref = SP.parseCoord(t.v);
      if (!ref) throw new CalcError('#NAME?');
      var colon = peek();
      if (colon && colon.t === 'op' && colon.v === ':') {
        pos++;
        var t2 = next();
        if (!t2 || t2.t !== 'name') throw new CalcError('#ERROR!');
        var ref2 = SP.parseCoord(t2.v);
        if (!ref2) throw new CalcError('#REF!');
        return {
          kind: 'range',
          r1: Math.min(ref.r, ref2.r), c1: Math.min(ref.c, ref2.c),
          r2: Math.max(ref.r, ref2.r), c2: Math.max(ref.c, ref2.c)
        };
      }
      return cellToValue(ref);
    }
    throw new CalcError('#ERROR!');
  }

  function callFunction(name) {
    var args = [];
    if (peek() && peek().t === 'op' && peek().v === ')') { pos++; }
    else {
      for (;;) {
        args.push(parseExpr());
        var t = next();
        if (!t) throw new CalcError('#ERROR!');
        if (t.t === 'op' && t.v === ',') continue;
        if (t.t === 'op' && t.v === ')') break;
        throw new CalcError('#ERROR!');
      }
    }
    return applyFunction(name, args);
  }

  function parseTerm() {
    var v = parseFactor();
    for (;;) {
      var t = peek();
      if (t && t.t === 'op' && (t.v === '*' || t.v === '/')) {
        pos++;
        var r = parseFactor();
        var a = numOf(v), b = numOf(r);
        if (t.v === '*') v = { kind: 'num', num: a * b };
        else { if (b === 0) throw new CalcError('#DIV/0!'); v = { kind: 'num', num: a / b }; }
      } else return v;
    }
  }

  function parseExpr() {
    var v = parseTerm();
    for (;;) {
      var t = peek();
      if (t && t.t === 'op' && (t.v === '+' || t.v === '-')) {
        pos++;
        var r = parseTerm();
        var a = numOf(v), b = numOf(r);
        v = { kind: 'num', num: t.v === '+' ? a + b : a - b };
      } else return v;
    }
  }

  var result = parseExpr();
  if (pos < tokens.length) throw new CalcError('#ERROR!');
  return { type: 'num', num: numOf(result), disp: SP.fmt(numOf(result)) };
}

function (formula, remapRow, remapCol) {
  var s = String(formula);
  if (s.charAt(0) !== '=') return s;
  var body = s.slice(1), bad = false;
  var out = body.replace(/(\$?)([A-Za-z]{1,3})(\$?)([0-9]{1,7})/g, function (m, cAbs, letters, rAbs, digits, offset, str) {
    var after = str.charAt(offset + m.length);
    if (after === '(' || /[A-Za-z0-9_]/.test(after)) return m;
    var c = SP.colNum(letters);
    var r = parseInt(digits, 10) - 1;
    if (c < 0) return m;
    var nr = remapRow ? remapRow(r) : r;
    var nc = remapCol ? remapCol(c) : c;
    if (nr == null || nc == null || nr < 0 || nc < 0) { bad = true; return m; }
    // Inserting or deleting rows/columns moves the reference together with its data, whatever
    // the absolute markers say; the markers themselves are kept in the expression.
    return cAbs + SP.colName(nc) + rAbs + (nr + 1);
  });
  if (bad) return '=#REF!';
  return '=' + out;
}

function (formula, dr, dc) {
  var s = String(formula);
  if (s.charAt(0) !== '=') return s;
  var body = s.slice(1), bad = false;
  var out = body.replace(/(\$?)([A-Za-z]{1,3})(\$?)([0-9]{1,7})/g, function (m, cAbs, letters, rAbs, digits, offset, str) {
    var after = str.charAt(offset + m.length);
    if (after === '(' || /[A-Za-z0-9_]/.test(after)) return m;
    var c = SP.colNum(letters);
    var r = parseInt(digits, 10) - 1;
    if (c < 0) return m;
    var nr = rAbs ? r : r + dr;
    var nc = cAbs ? c : c + dc;
    if (nr < 0 || nc < 0) { bad = true; return m; }
    return cAbs + SP.colName(nc) + rAbs + (nr + 1);
  });
  return bad ? '=#REF!' : '=' + out;
}

function (raw, dr, dc) {
  if (String(raw).charAt(0) !== '=') return raw;
  return SP.shiftFormula(raw, dr, dc);
}

function (sheet, from, count) {
  SP.adjustPivotRanges(sheet, 'row', from, count, 'insert');
  var cells = sheet.cells || {}, out = {};
  for (var coord in cells) {
    if (!Object.prototype.hasOwnProperty.call(cells, coord)) continue;
    var p = SP.parseCoord(coord);
    if (!p) continue;
    var r = p.r >= from ? p.r + count : p.r;
    var raw = String(cells[coord]);
    out[SP.coord(r, p.c)] = raw.charAt(0) === '='
      ? SP.remapRefs(raw, function (rr) { return rr >= from ? rr + count : rr; }, null)
      : raw;
  }
  sheet.cells = out;
  SP.setRules(sheet, SP.rules(sheet).map(function (v) {
    var rg = SP.parseRange(v.range);
    if (!rg) return v;
    var r1 = rg.r1 >= from ? rg.r1 + count : rg.r1;
    var r2 = rg.r2 >= from ? rg.r2 + count : rg.r2;
    return Object.assign({}, v, { range: SP.rangeName({ c1: rg.c1, c2: rg.c2, r1: r1, r2: r2 }) });
  }));
}

function (sheet, at, count) {
  SP.adjustPivotRanges(sheet, 'row', at, count, 'delete');
  var cells = sheet.cells || {}, out = {};
  for (var coord in cells) {
    if (!Object.prototype.hasOwnProperty.call(cells, coord)) continue;
    var p = SP.parseCoord(coord);
    if (!p) continue;
    if (p.r >= at && p.r < at + count) continue;
    var r = p.r >= at + count ? p.r - count : p.r;
    var raw = String(cells[coord]);
    out[SP.coord(r, p.c)] = raw.charAt(0) === '='
      ? SP.remapRefs(raw, function (rr) {
        if (rr >= at && rr < at + count) return null;
        return rr >= at + count ? rr - count : rr;
      }, null)
      : raw;
  }
  sheet.cells = out;
  SP.setRules(sheet, SP.rules(sheet).filter(function (v) {
    var rg = SP.parseRange(v.range);
    return !(rg && rg.r1 >= at && rg.r2 < at + count);
  }).map(function (v) {
    var rg = SP.parseRange(v.range);
    if (!rg) return v;
    var r1 = rg.r1 >= at + count ? rg.r1 - count : rg.r1;
    var r2 = rg.r2 >= at + count ? rg.r2 - count : rg.r2;
    return Object.assign({}, v, { range: SP.rangeName({ c1: rg.c1, c2: rg.c2, r1: r1, r2: r2 }) });
  }));
}

