    out[SP.coord(p.r, c)] = raw.charAt(0) === '='
      ? SP.remapRefs(raw, null, function (cc) {
        if (cc >= at && cc < at + count) return null;
        return cc >= at + count ? cc - count : cc;
      })
      : raw;
  }
  sheet.cells = out;
  SP.setRules(sheet, SP.rules(sheet).filter(function (v) {
    var rg = SP.parseRange(v.range);
    return !(rg && rg.c1 >= at && rg.c2 < at + count);
  }).map(function (v) {
    var rg = SP.parseRange(v.range);
    if (!rg) return v;
    var c1 = rg.c1 >= at + count ? rg.c1 - count : rg.c1;
    var c2 = rg.c2 >= at + count ? rg.c2 - count : rg.c2;
    return Object.assign({}, v, { range: SP.rangeName({ r1: rg.r1, r2: rg.r2, c1: c1, c2: c2 }) });
  }));
}

function (sheet) {
  var list = SP.workbooks(), wb = null;
  for (var i = 0; i < list.length && !wb; i++) {
    var ws = (list[i] && list[i].worksheets) || [];
    for (var j = 0; j < ws.length; j++) {
      if (ws[j] === sheet || (sheet && ws[j].id === sheet.id)) { wb = list[i]; break; }
    }
  }
  return (wb ? wb.id : '?') + '/' + (sheet && sheet.id ? sheet.id : '?');
}

function (sheet) {
  var ui = ARC.state.ui || (ARC.state.ui = {});
  if (!ui.rules || typeof ui.rules !== 'object') ui.rules = {};
  var key = SP.rulesKey(sheet);
  if (!Array.isArray(ui.rules[key])) ui.rules[key] = [];
  return ui.rules[key];
}

function (sheet, list) {
  var ui = ARC.state.ui || (ARC.state.ui = {});
  if (!ui.rules || typeof ui.rules !== 'object') ui.rules = {};
  ui.rules[SP.rulesKey(sheet)] = list || [];
}

function (sheet, coord) {
  var p = SP.parseCoord(coord);
  if (!p) return null;
