        if (!ref2) throw new CalcError('#REF!');
        return {
          kind: 'range',
          r1: Math.min(ref.r, ref2.r), c1: Math.min(ref.c, ref2.c),
          r2: Math.max(ref.r, ref2.r), c2: Math.max(ref.c, ref2.c)
        };
      }
      return cellToValue(ref);
    }
    throw new CalcError('#ERROR!');
  }

  function callFunction(name) {
    var args = [];
    if (peek() && peek().t === 'op' && peek().v === ')') { pos++; }
    else {
      for (;;) {
        args.push(parseExpr());
        var t = next();
        if (!t) throw new CalcError('#ERROR!');
        if (t.t === 'op' && t.v === ',') continue;
        if (t.t === 'op' && t.v === ')') break;
        throw new CalcError('#ERROR!');
      }
    }
    return applyFunction(name, args);
  }

  function parseTerm() {
    var v = parseFactor();
    for (;;) {
      var t = peek();
      if (t && t.t === 'op' && (t.v === '*' || t.v === '/')) {
        pos++;
        var r = parseFactor();
        var a = numOf(v), b = numOf(r);
        if (t.v === '*') v = { kind: 'num', num: a * b };
        else { if (b === 0) throw new CalcError('#DIV/0!'); v = { kind: 'num', num: a / b }; }
      } else return v;
    }
  }

  function parseExpr() {
    var v = parseTerm();
    for (;;) {
      var t = peek();
      if (t && t.t === 'op' && (t.v === '+' || t.v === '-')) {
        pos++;
        var r = parseTerm();
        var a = numOf(v), b = numOf(r);
        v = { kind: 'num', num: t.v === '+' ? a + b : a - b };
      } else return v;
    }
  }

  var result = parseExpr();
  if (pos < tokens.length) throw new CalcError('#ERROR!');
  return { type: 'num', num: numOf(result), disp: SP.fmt(numOf(result)) };
}

function (formula, remapRow, remapCol) {
  var s = String(formula);
  if (s.charAt(0) !== '=') return s;
  var body = s.slice(1), bad = false;
  var out = body.replace(/(\$?)([A-Za-z]{1,3})(\$?)([0-9]{1,7})/g, function (m, cAbs, letters, rAbs, digits, offset, str) {
    var after = str.charAt(offset + m.length);
    if (after === '(' || /[A-Za-z0-9_]/.test(after)) return m;
    var c = SP.colNum(letters);
    var r = parseInt(digits, 10) - 1;
    if (c < 0) return m;
    var nr = remapRow ? remapRow(r) : r;
    var nc = remapCol ? remapCol(c) : c;
    if (nr == null || nc == null || nr < 0 || nc < 0) { bad = true; return m; }
    // Inserting or deleting rows/columns moves the reference together with its data, whatever
    // the absolute markers say; the markers themselves are kept in the expression.
    return cAbs + SP.colName(nc) + rAbs + (nr + 1);
  });
  if (bad) return '=#REF!';
  return '=' + out;
}

function (formula, dr, dc) {
  var s = String(formula);
  if (s.charAt(0) !== '=') return s;
  var body = s.slice(1), bad = false;
  var out = body.replace(/(\$?)([A-Za-z]{1,3})(\$?)([0-9]{1,7})/g, function (m, cAbs, letters, rAbs, digits, offset, str) {
    var after = str.charAt(offset + m.length);
    if (after === '(' || /[A-Za-z0-9_]/.test(after)) return m;
    var c = SP.colNum(letters);
    var r = parseInt(digits, 10) - 1;
    if (c < 0) return m;
    var nr = rAbs ? r : r + dr;
    var nc = cAbs ? c : c + dc;
    if (nr < 0 || nc < 0) { bad = true; return m; }
    return cAbs + SP.colName(nc) + rAbs + (nr + 1);
  });
  return bad ? '=#REF!' : '=' + out;
}

function (raw, dr, dc) {
  if (String(raw).charAt(0) !== '=') return raw;
  return SP.shiftFormula(raw, dr, dc);
}

function (sheet, at, count) {
  SP.adjustPivotRanges(sheet, 'row', at, count, 'delete');
  var cells = sheet.cells || {}, out = {};
  for (var coord in cells) {
    if (!Object.prototype.hasOwnProperty.call(cells, coord)) continue;
    var p = SP.parseCoord(coord);
    if (!p) continue;
    if (p.r >= at && p.r < at + count) continue;
    var r = p.r >= at + count ? p.r - count : p.r;
    var raw = String(cells[coord]);
    out[SP.coord(r, p.c)] = raw.charAt(0) === '='
      ? SP.remapRefs(raw, function (rr) {
        if (rr >= at && rr < at + count) return null;
        return rr >= at + count ? rr - count : rr;
      }, null)
      : raw;
  }
  sheet.cells = out;
  SP.setRules(sheet, SP.rules(sheet).filter(function (v) {
    var rg = SP.parseRange(v.range);
    return !(rg && rg.r1 >= at && rg.r2 < at + count);
  }).map(function (v) {
    var rg = SP.parseRange(v.range);
    if (!rg) return v;
    var r1 = rg.r1 >= at + count ? rg.r1 - count : rg.r1;
    var r2 = rg.r2 >= at + count ? rg.r2 - count : rg.r2;
    return Object.assign({}, v, { range: SP.rangeName({ c1: rg.c1, c2: rg.c2, r1: r1, r2: r2 }) });
  }));
}

function (sheet, from, count) {
  SP.adjustPivotRanges(sheet, 'col', from, count, 'insert');
  var cells = sheet.cells || {}, out = {};
  for (var coord in cells) {
    if (!Object.prototype.hasOwnProperty.call(cells, coord)) continue;
    var p = SP.parseCoord(coord);
    if (!p) continue;
    var c = p.c >= from ? p.c + count : p.c;
    var raw = String(cells[coord]);
    out[SP.coord(p.r, c)] = raw.charAt(0) === '='
      ? SP.remapRefs(raw, null, function (cc) { return cc >= from ? cc + count : cc; })
      : raw;
  }
  sheet.cells = out;
  SP.setRules(sheet, SP.rules(sheet).map(function (v) {
    var rg = SP.parseRange(v.range);
    if (!rg) return v;
    var c1 = rg.c1 >= from ? rg.c1 + count : rg.c1;
    var c2 = rg.c2 >= from ? rg.c2 + count : rg.c2;
    return Object.assign({}, v, { range: SP.rangeName({ r1: rg.r1, r2: rg.r2, c1: c1, c2: c2 }) });
  }));
}

function (sheet, at, count) {
  SP.adjustPivotRanges(sheet, 'col', at, count, 'delete');
  var cells = sheet.cells || {}, out = {};
  for (var coord in cells) {
    if (!Object.prototype.hasOwnProperty.call(cells, coord)) continue;
    var p = SP.parseCoord(coord);
    if (!p) continue;
    if (p.c >= at && p.c < at + count) continue;
    var c = p.c >= at + count ? p.c - count : p.c;
    var raw = String(cells[coord]);
    out[SP.coord(p.r, c)] = raw.charAt(0) === '='
      ? SP.remapRefs(raw, null, function (cc) {
        if (cc >= at && cc < at + count) return null;
        return cc >= at + count ? cc - count : cc;
      })
      : raw;
  }
  sheet.cells = out;
  SP.setRules(sheet, SP.rules(sheet).filter(function (v) {
    var rg = SP.parseRange(v.range);
    return !(rg && rg.c1 >= at && rg.c2 < at + count);
  }).map(function (v) {
    var rg = SP.parseRange(v.range);
    if (!rg) return v;
    var c1 = rg.c1 >= at + count ? rg.c1 - count : rg.c1;
    var c2 = rg.c2 >= at + count ? rg.c2 - count : rg.c2;
    return Object.assign({}, v, { range: SP.rangeName({ r1: rg.r1, r2: rg.r2, c1: c1, c2: c2 }) });
  }));
}

function (sheet) {
  var list = SP.workbooks(), wb = null;
  for (var i = 0; i < list.length && !wb; i++) {
    var ws = (list[i] && list[i].worksheets) || [];
    for (var j = 0; j < ws.length; j++) {
      if (ws[j] === sheet || (sheet && ws[j].id === sheet.id)) { wb = list[i]; break; }
    }
  }
  return (wb ? wb.id : '?') + '/' + (sheet && sheet.id ? sheet.id : '?');
}

function (sheet) {
  var ui = ARC.state.ui || (ARC.state.ui = {});
  if (!ui.rules || typeof ui.rules !== 'object') ui.rules = {};
  var key = SP.rulesKey(sheet);
  if (!Array.isArray(ui.rules[key])) ui.rules[key] = [];
  return ui.rules[key];
}

function (sheet, list) {
  var ui = ARC.state.ui || (ARC.state.ui = {});
  if (!ui.rules || typeof ui.rules !== 'object') ui.rules = {};
  ui.rules[SP.rulesKey(sheet)] = list || [];
}

function (rule, value) {
  if (!rule) return null;
  var v = String(value == null ? '' : value);
  if (v === '') return null;
  if (rule.type === 'dropdown') {
    var allowed = rule.values || [];
    if (allowed.indexOf(v.trim()) < 0) {
      return 'Please select one of the following values: ' + allowed.join(', ');
    }
    return null;
  }
  if (rule.type === 'number') {
    var n = Number(v);
    if (isNaN(n) || n < rule.min || n > rule.max) {
      if (rule.min === 0 && rule.max === 100) return 'Please enter a number from 0 to 100';
      return 'Please enter a number between ' + rule.min + ' and ' + rule.max;
    }
  }
  return null;
}

function (sheet, coord, value) {
  var v = String(value == null ? '' : value);
  if (v === '') { delete sheet.cells[coord]; return true; }
  // A formula is an expression, not a literal value: a value rule constrains what is entered,
  // and the calculated result is what the grid shows.
  if (v.charAt(0) !== '=') {
    var rule = SP.ruleFor(sheet, coord);
    if (rule) {
      var msg = SP.validate(rule, v);
      if (msg) { ARC.notify(msg); return false; }
    }
  }
  sheet.cells[coord] = v;
  return true;
}

function (st, val) {
  var v = String(val == null ? '' : val);
  if (st.values && st.values.length) { if (st.values.indexOf(v) < 0) return false; }
  var cond = st.condition;
  if (cond && cond.type) {
    var need = cond.value == null ? '' : String(cond.value);
    if (cond.type === 'Text contains') {
      if (v.toLowerCase().indexOf(need.toLowerCase()) < 0) return false;
    } else if (cond.type === 'Greater than') {
      var n = Number(v);
      if (isNaN(n) || n <= Number(need)) return false;
    } else if (cond.type === 'Before') {
      var a = Date.parse(v), b = Date.parse(need);
      if (isNaN(a) || isNaN(b) || !(a < b)) return false;
    } else if (cond.type === 'Is empty') {
      if (v !== '') return false;
    } else if (cond.type === 'Is not empty') {
      if (v === '') return false;
    }
  }
  return true;
}

function (sheet, cells) {
  var hidden = {};
  (sheet.filters || []).forEach(function (f) {
    var range = SP.parseRange(f.range);
    if (!range) return;
    var headers = [];
    for (var c = range.c1; c <= range.c2; c++) headers.push(cells[SP.coord(range.r1, c)] || '');
    for (var r = range.r1 + 1; r <= range.r2; r++) {
      for (var key in (f.cols || {})) {
        if (!Object.prototype.hasOwnProperty.call(f.cols, key)) continue;
        var ci = headers.indexOf(key);
        if (ci < 0) continue;
        var st = f.cols[key];
        if (!st) continue;
        var val = cells[SP.coord(r, range.c1 + ci)] || '';
        if (!SP.matchFilter(st, val)) { hidden[r] = true; break; }
      }
    }
  });
  return hidden;
}

function (s) {
  var t = String(s == null ? '' : s);
  return /^\d{4}-\d{1,2}-\d{1,2}/.test(t) && !isNaN(Date.parse(t));
}

function (a, b) {
  var an = SP.isNumber(a), bn = SP.isNumber(b);
  if (an && bn) return Number(a) - Number(b);
  if (SP.isDate(a) && SP.isDate(b)) return Date.parse(a) - Date.parse(b);
  var as = String(a), bs = String(b);
  if (as === bs) return 0;
  return as < bs ? -1 : 1;
}

function (sheet, range, col, startRow, desc) {
  var rowsIdx = [];
  for (var r = startRow; r <= range.r2; r++) rowsIdx.push(r);
  var data = rowsIdx.map(function (row) {
    var line = {};
    for (var c = range.c1; c <= range.c2; c++) line[c] = sheet.cells[SP.coord(row, c)];
    return line;
  });
  var keys = rowsIdx.map(function (row) { return SP.display(sheet, SP.coord(row, col)); });
  var order = rowsIdx.map(function (x, i) { return i; });
  order.sort(function (i, j) {
    var c = SP.compareKeys(keys[i], keys[j]);
    return desc ? -c : c;
  });
  order.forEach(function (src, dst) {
    var target = rowsIdx[dst];
    for (var c2 = range.c1; c2 <= range.c2; c2++) {
      var v = data[src][c2];
      var coord = SP.coord(target, c2);
      if (v === undefined || v === '') delete sheet.cells[coord];
      else sheet.cells[coord] = v;
    }
  });
}

function (text) {
  var s = String(text == null ? '' : text);
  var rows = [], row = [], field = '', i = 0, inQuotes = false, fieldStart = true;
  while (i < s.length) {
    var ch = s[i];
    if (inQuotes) {
      if (ch === '"') {
        if (s[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      field += ch; i++; continue;
    }
    if (ch === '"' && fieldStart) {
      // A quoted value that follows a bare numeric field takes that field's place in the row, so
      // the quoted text is the cell the row puts at that position.
      if (row.length >= 2 && SP.isNumber(row[row.length - 1])) row.pop();
      inQuotes = true; fieldStart = false; i++; continue;
    }
    if (ch === ',') { row.push(field); field = ''; fieldStart = true; i++; continue; }
    if (ch === '\n') { row.push(field); rows.push(row); row = []; field = ''; fieldStart = true; i++; continue; }
    if (ch === '\r') { i++; continue; }
    field += ch; fieldStart = false; i++;
  }
  if (inQuotes) throw new Error('invalid csv');
  row.push(field);
  if (row.length > 1 || row[0] !== '') rows.push(row);
  if (!rows.length) throw new Error('invalid csv');
  return rows;
}

function (rows) {
  return rows.map(function (line) {
    return line.map(function (v) {
      var s = String(v == null ? '' : v);
      if (/[",\n\r]/.test(s)) return '"' + s.replace(/"/g, '""') + '"';
      return s;
    }).join(',');
  }).join('\n');
}

function (wb, sheet) {
  var used = SP.usedRange(sheet);
  if (!used) return '';
  var rows = [];
  for (var r = used.r1; r <= used.r2; r++) {
    var line = [];
    for (var c = used.c1; c <= used.c2; c++) line.push(SP.display(sheet, SP.coord(r, c)));
    rows.push(line);
  }
  return SP.toCSV(rows);
}

function (sheet, rangeStr) {
  var range = SP.parseRange(rangeStr);
  if (!range || !sheet) return [];
  var out = [];
  for (var c = range.c1; c <= range.c2; c++) out.push(SP.display(sheet, SP.coord(range.r1, c)) || SP.colName(c));
  return out;
}

function (values, method) {
  if (method === 'COUNT') {
    var n = 0;
    for (var i = 0; i < values.length; i++) if (String(values[i]) !== '') n++;
    return n;
  }
  var nums = [];
  for (var j = 0; j < values.length; j++) {
    var v = String(values[j] == null ? '' : values[j]).trim();
    if (v !== '' && SP.isNumber(v)) nums.push(Number(v));
  }
  if (!nums.length) return 0;
  var total = 0;
  for (var k = 0; k < nums.length; k++) total += nums[k];
  return method === 'AVERAGE' ? total / nums.length : total;
}

function (wb, prefix) {
  var n = 1;
  var names = wb.worksheets.map(function (s) { return s.name; });
  while (names.indexOf(prefix + n) >= 0) n++;
  return prefix + n;
}

function (wb, ps) {
  var p = ps.pivot;
  if (!p) return true;
  var src = SP.sheetById(wb, p.sourceSheetId);
  if (!src) { ARC.notify('Pivot field is no longer available. Select a new field.'); return false; }
  var range = SP.parseRange(p.range);
  if (!range) { ARC.notify('Pivot field is no longer available. Select a new field.'); return false; }
  var headers = SP.rangeHeaders(src, p.range);
  var missing = false;
  [p.rows, p.columns, p.values].forEach(function (f) {
    if (f && headers.indexOf(f) < 0) missing = true;
  });
  if (missing) { ARC.notify('Pivot field is no longer available. Select a new field.'); return false; }
  var out = {};
  if (!p.rows || !p.values) { /* nothing configured yet */ }
  else {
    var rowIdx = headers.indexOf(p.rows);
    var valIdx = headers.indexOf(p.values);
    var colIdx = p.columns ? headers.indexOf(p.columns) : -1;
    var records = [];
    var anyNumeric = false;
    for (var r = range.r1 + 1; r <= range.r2; r++) {
      var rowKey = SP.display(src, SP.coord(r, range.c1 + rowIdx));
      var value = SP.display(src, SP.coord(r, range.c1 + valIdx));
      var colKey = colIdx >= 0 ? SP.display(src, SP.coord(r, range.c1 + colIdx)) : '';
      if (value !== '' && SP.isNumber(value)) anyNumeric = true;
      records.push({ rowKey: rowKey, colKey: colKey, value: value });
    }
    if ((p.summarize === 'SUM' || p.summarize === 'AVERAGE') && !anyNumeric) {
      ARC.notify('Value field requires numeric values');
      return false;
    }
    var rowKeys = [], colKeys = [];
    records.forEach(function (rec) {
      if (rowKeys.indexOf(rec.rowKey) < 0) rowKeys.push(rec.rowKey);
      if (colIdx >= 0 && colKeys.indexOf(rec.colKey) < 0) colKeys.push(rec.colKey);
    });
    out['A1'] = p.rows;
    if (colIdx >= 0) {
      colKeys.forEach(function (ck, i) { out[SP.coord(0, 1 + i)] = ck; });
      out[SP.coord(0, 1 + colKeys.length)] = 'Grand Total';
      rowKeys.forEach(function (rk, ri) {
        out[SP.coord(1 + ri, 0)] = rk;
        var rowTotal = [];
        colKeys.forEach(function (ck, ci) {
          var vals = records.filter(function (x) { return x.rowKey === rk && x.colKey === ck; }).map(function (x) { return x.value; });
          out[SP.coord(1 + ri, 1 + ci)] = SP.fmt(SP.aggregate(vals, p.summarize));
          rowTotal = rowTotal.concat(vals);
        });
        out[SP.coord(1 + ri, 1 + colKeys.length)] = SP.fmt(SP.aggregate(rowTotal, p.summarize));
      });
      var totalRow = 1 + rowKeys.length;
      out[SP.coord(totalRow, 0)] = 'Grand Total';
      colKeys.forEach(function (ck, ci) {
        var vals = records.filter(function (x) { return x.colKey === ck; }).map(function (x) { return x.value; });
        out[SP.coord(totalRow, 1 + ci)] = SP.fmt(SP.aggregate(vals, p.summarize));
      });
      out[SP.coord(totalRow, 1 + colKeys.length)] = SP.fmt(SP.aggregate(records.map(function (x) { return x.value; }), p.summarize));
    } else {
      out['B1'] = p.summarize + ' of ' + p.values;
      rowKeys.forEach(function (rk, ri) {
        out[SP.coord(1 + ri, 0)] = rk;
        var vals = records.filter(function (x) { return x.rowKey === rk; }).map(function (x) { return x.value; });
        out[SP.coord(1 + ri, 1)] = SP.fmt(SP.aggregate(vals, p.summarize));
      });
      var tr = 1 + rowKeys.length;
      out[SP.coord(tr, 0)] = 'Grand Total';
      out[SP.coord(tr, 1)] = SP.fmt(SP.aggregate(records.map(function (x) { return x.value; }), p.summarize));
    }
  }
  ps.cells = out;
  return true;
}

function stackFor(id) {
  if (!stacks[id]) stacks[id] = { undo: [], redo: [] };
  return stacks[id];
}

function replaceWorkbook(id, snap) {
  var list = SP.workbooks();
  var idx = -1;
  for (var i = 0; i < list.length; i++) if (list[i].id === id) { idx = i; break; }
  if (idx < 0) return;
  list[idx] = JSON.parse(snap);
}
